writeNewRepair("omniflow-backend-patch/portal_model_router.py", "def failover_for(", false,
    "\"\"\"Model Router (\u00a7229) - which model answers which AI task, with failover.\n\nTwo providers:\n- primary   = the AI engine (Admin > Integrations > AI engine / OF_LLM_*),\n- secondary = an optional second OpenAI-compatible provider (another\n  vendor, or a second key on the same one).\nTwo tiers on top of them:\n- fast  = light classification work (intent, sentiment, workflow branch),\n- smart = customer-facing writing (brain replies, negotiation, copy, ...).\nEach tier picks a provider and a model; every routable feature picks a\ntier (fast | smart | main), with sensible defaults. ``main`` is the AI\nengine exactly as before.\n\nFailover: when the chosen provider does not answer (transport error,\nHTTP error, timeout) the call is retried once on the other provider. A\nprovider answering with unusable JSON is NOT failed over (that is the\nmodel, not the provider). A small in-process circuit breaker skips a\nprovider after N consecutive failures for S seconds when the other one\ncan serve the call.\n\nZero configuration = today's behaviour: blank tier models resolve to the\nAI engine's model on the AI engine, and failover needs a secondary key.\nDedicated routes keep their own settings (assistant, image understanding,\nvoice notes, knowledge embeddings) and are shown on the admin page.\n\nStandard library only (portal_llm imports this on the hot path); config\nis read through platform_settings' 30-second cache with env fallbacks.\nAdmin API (service key): GET /api/v1/admin/ai/router, POST .../test.\nSaving goes through the existing PUT /api/v1/admin/providers (group\n``router``), validated by clean_value() below.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport re\nimport secrets as _secrets\nimport threading\nimport time\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nlogger = logging.getLogger(\"omniflow.model-router\")\n\nMODES = (\"on\", \"off\")\nPROVIDERS = (\"primary\", \"secondary\")\nTIERS = (\"fast\", \"smart\", \"main\")\n\n#: feature -> default tier. Only features that call portal_llm.chat_json.\nROUTABLE: Tuple[Tuple[str, str], ...] = (\n    (\"brain\", \"smart\"),\n    (\"voice_call\", \"smart\"),\n    (\"negotiation\", \"smart\"),\n    (\"copy\", \"smart\"),\n    (\"bi_narrative\", \"smart\"),\n    (\"site_analyzer\", \"smart\"),\n    (\"ai_quality_label\", \"smart\"),\n    (\"workflow\", \"fast\"),\n    (\"intent\", \"fast\"),\n    (\"sentiment\", \"fast\"),\n    (\"other\", \"main\"),\n)\nDEFAULT_TIERS = dict(ROUTABLE)\n\nTEST_TIMEOUT_SECONDS = float(os.environ.get(\"OF_ROUTER_TEST_TIMEOUT\", \"12\") or 12)\nMAX_MODEL_CHARS = 120\nMAX_DAYS = 90\n_MODEL_RE = re.compile(r\"^[A-Za-z0-9._:/@+\\-]{1,120}$\")\n_URL_RE = re.compile(r\"^https?://[^\\s?#]+$\")\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    return os.environ.get(name, default).strip()\n\n\ndef _setting(name: str, env: str, default: str = \"\") -> str:\n    \"\"\"Admin panel first (cached), env fallback, then default.\"\"\"\n    value = \"\"\n    try:\n        import platform_settings\n\n        value = platform_settings._cached(\"router.\" + name)\n    except Exception:\n        value = \"\"\n    return value or _env(env, default)\n\n\ndef _bounded(raw: str, default: int, low: int, high: int) -> int:\n    try:\n        value = int(str(raw or \"\").strip() or default)\n    except (TypeError, ValueError):\n        value = default\n    return max(low, min(high, value))\n\n\ndef parse_routes(raw: Any) -> Dict[str, str]:\n    \"\"\"routes_json -> {feature: tier}; unknown features / tiers dropped.\"\"\"\n    try:\n        data = json.loads(raw) if isinstance(raw, str) and raw.strip() else raw\n    except Exception:\n        return {}\n    if not isinstance(data, dict):\n        return {}\n    return {str(k): str(v) for k, v in data.items()\n            if str(k) in DEFAULT_TIERS and str(v) in TIERS}\n\n\ndef settings() -> Dict[str, Any]:\n    \"\"\"Effective router config (fail-soft, never raises).\"\"\"\n    mode = _setting(\"mode\", \"OF_ROUTER_MODE\", \"on\").lower()\n    failover = _setting(\"failover\", \"OF_ROUTER_FAILOVER\", \"on\").lower()\n    tiers = {}\n    for tier in (\"fast\", \"smart\"):\n        provider = _setting(tier + \"_provider\",\n                            \"OF_ROUTER_\" + tier.upper() + \"_PROVIDER\",\n                            \"primary\").lower()\n        tiers[tier] = {\n            \"provider\": provider if provider in PROVIDERS else \"primary\",\n            \"model\": _setting(tier + \"_model\",\n                              \"OF_ROUTER_\" + tier.upper() + \"_MODEL\"),\n        }\n    return {\n        \"mode\": mode if mode in MODES else \"on\",\n        \"failover\": failover if failover in MODES else \"on\",\n        \"tiers\": tiers,\n        \"routes\": parse_routes(_setting(\"routes_json\", \"OF_ROUTER_ROUTES_JSON\")),\n        \"secondary\": {\n            \"base_url\": _setting(\"secondary_base_url\",\n                                 \"OF_ROUTER_SECONDARY_BASE_URL\").rstrip(\"/\"),\n            \"api_key\": _setting(\"secondary_api_key\",\n                                \"OF_ROUTER_SECONDARY_API_KEY\"),\n            \"model\": _setting(\"secondary_model\", \"OF_ROUTER_SECONDARY_MODEL\"),\n        },\n        \"breaker_failures\": _bounded(\n            _setting(\"breaker_failures\", \"OF_ROUTER_BREAKER_FAILURES\"), 3, 1, 20),\n        \"breaker_seconds\": _bounded(\n            _setting(\"breaker_seconds\", \"OF_ROUTER_BREAKER_SECONDS\"), 60, 10, 3600),\n    }\n\n\ndef tier_for(feature: str, config: Optional[Dict[str, Any]] = None) -> str:\n    config = config if config is not None else settings()\n    feature = feature if feature in DEFAULT_TIERS else \"other\"\n    return config[\"routes\"].get(feature) or DEFAULT_TIERS[feature]\n\n\n# ---------------------------------------------------------------------------\n# circuit breaker (per process; serverless instances each keep their own)\n# ---------------------------------------------------------------------------\n\n_LOCK = threading.Lock()\n_BREAKER: Dict[str, Dict[str, Any]] = {}\n\n\ndef note(provider: str, ok: bool, config: Optional[Dict[str, Any]] = None) -> None:\n    \"\"\"Record one provider outcome; opens the breaker after N failures.\"\"\"\n    if provider not in PROVIDERS:\n        return\n    try:\n        config = config if config is not None else settings()\n        with _LOCK:\n            state = _BREAKER.setdefault(provider, {\n                \"failures\": 0, \"open_until\": 0.0, \"last_failure_at\": 0.0})\n            if ok:\n                state[\"failures\"] = 0\n                state[\"open_until\"] = 0.0\n                return\n            state[\"failures\"] += 1\n            state[\"last_failure_at\"] = time.time()\n            if state[\"failures\"] >= config[\"breaker_failures\"]:\n                state[\"open_until\"] = time.time() + config[\"breaker_seconds\"]\n                logger.warning(\"model router: %s provider paused for %ss after\"\n                               \" %s failures\", provider,\n                               config[\"breaker_seconds\"], state[\"failures\"])\n    except Exception:\n        pass\n\n\ndef is_open(provider: str) -> bool:\n    with _LOCK:\n        state = _BREAKER.get(provider)\n        return bool(state and state[\"open_until\"] > time.time())\n\n\ndef breaker_state() -> Dict[str, Dict[str, Any]]:\n    now = time.time()\n    out = {}\n    with _LOCK:\n        for provider in PROVIDERS:\n            state = _BREAKER.get(provider) or {}\n            until = float(state.get(\"open_until\") or 0.0)\n            out[provider] = {\n                \"failures\": int(state.get(\"failures\") or 0),\n                \"paused\": until > now,\n                \"paused_seconds_left\": max(0, int(until - now)),\n            }\n    return out\n\n\ndef reset_breaker() -> None:\n    with _LOCK:\n        _BREAKER.clear()\n\n\n# ---------------------------------------------------------------------------\n# planning (portal_llm calls this for every chat_json)\n# ---------------------------------------------------------------------------\n\ndef _target(provider: str, base_url: str, api_key: str, model: str,\n            route: str) -> Dict[str, Any]:\n    return {\"provider\": provider, \"base_url\": str(base_url or \"\").rstrip(\"/\"),\n            \"api_key\": str(api_key or \"\"), \"model\": str(model or \"\"),\n            \"route\": route}\n\n\ndef plan(feature: str, primary: Dict[str, Any],\n         config: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:\n    \"\"\"Ordered targets for one call: [chosen] or [chosen, failover].\n\n    ``primary`` = the AI engine runtime (base_url, api_key, model).\n    ``route`` on a target is \"\" when it is exactly the AI engine (the\n    ledger then looks like before), else fast | smart | failover.\n    \"\"\"\n    main = _target(\"primary\", primary.get(\"base_url\"), primary.get(\"api_key\"),\n                   primary.get(\"model\"), \"\")\n    config = config if config is not None else settings()\n    if config[\"mode\"] != \"on\":\n        return [main]\n    secondary = config[\"secondary\"]\n    has_secondary = bool(secondary[\"api_key\"])\n    secondary_base = secondary[\"base_url\"] or main[\"base_url\"]\n    tier = tier_for(feature, config)\n    first = main\n    if tier in (\"fast\", \"smart\"):\n        chosen = config[\"tiers\"][tier]\n        if chosen[\"provider\"] == \"secondary\" and has_secondary:\n            first = _target(\"secondary\", secondary_base, secondary[\"api_key\"],\n                            chosen[\"model\"] or secondary[\"model\"]\n                            or main[\"model\"], tier)\n        elif chosen[\"model\"] and chosen[\"model\"] != main[\"model\"]:\n            first = _target(\"primary\", main[\"base_url\"], main[\"api_key\"],\n                            chosen[\"model\"], tier)\n    targets = [first]\n    if config[\"failover\"] == \"on\" and has_secondary:\n        if first[\"provider\"] == \"primary\":\n            second = _target(\"secondary\", secondary_base, secondary[\"api_key\"],\n                             secondary[\"model\"] or first[\"model\"], \"failover\")\n        else:\n            second = dict(main, route=\"failover\")\n        if is_open(first[\"provider\"]) and not is_open(second[\"provider\"]):\n            return [second]\n        targets.append(second)\n    return targets\n\n\ndef failover_for(model: str, config: Optional[Dict[str, Any]] = None\n                 ) -> Optional[Dict[str, Any]]:\n    \"\"\"The secondary provider as a failover target for a dedicated route\n    (the owner assistant), or None when failover is off / not set up.\"\"\"\n    try:\n        config = config if config is not None else settings()\n    except Exception:\n        return None\n    secondary = config[\"secondary\"]\n    if config[\"mode\"] != \"on\" or config[\"failover\"] != \"on\" \\\n            or not secondary[\"api_key\"]:\n        return None\n    base = secondary[\"base_url\"]\n    if not base:\n        try:\n            import platform_settings\n\n            base = platform_settings.llm_config().get(\"base_url\") or \"\"\n        except Exception:\n            base = \"\"\n    if not base:\n        return None\n    return _target(\"secondary\", base, secondary[\"api_key\"],\n                   secondary[\"model\"] or model, \"failover\")\n\n\n# ---------------------------------------------------------------------------\n# admin validation (called by admin_providers for group \"router\")\n# ---------------------------------------------------------------------------\n\ndef clean_value(name: str, text: str) -> Tuple[str, Optional[str]]:\n    \"\"\"Normalise one router setting; (value, None) or (value, error).\"\"\"\n    text = str(text or \"\").strip()\n    full = \"router.\" + name\n    if not text:\n        return \"\", None\n    if name in (\"mode\", \"failover\"):\n        text = text.lower()\n        if text not in MODES:\n            return text, full + \" must be on or off.\"\n    elif name in (\"fast_provider\", \"smart_provider\"):\n        text = text.lower()\n        if text not in PROVIDERS:\n            return text, full + \" must be primary or secondary.\"\n    elif name in (\"fast_model\", \"smart_model\", \"secondary_model\"):\n        if not _MODEL_RE.match(text):\n            return text, (full + \" must be a model name without spaces (\"\n                          + str(MAX_MODEL_CHARS) + \" characters max).\")\n    elif name == \"secondary_base_url\":\n        text = text.rstrip(\"/\")\n        if len(text) > 300 or not _URL_RE.match(text):\n            return text, (full + \" must be an http(s) address such as\"\n                          \" https://api.groq.com/openai/v1 (no query).\")\n    elif name == \"secondary_api_key\":\n        if len(text) > 400 or any(ch.isspace() for ch in text):\n            return text, full + \" looks wrong (no spaces, 400 characters max).\"\n    elif name == \"routes_json\":\n        try:\n            data = json.loads(text)\n        except Exception:\n            return text, full + \" must be a JSON object.\"\n        if not isinstance(data, dict):\n            return text, full + \" must be a JSON object.\"\n        for key, value in data.items():\n            if key not in DEFAULT_TIERS:\n                return text, full + \": unknown task \\\"\" + str(key)[:40] + \"\\\".\"\n            if value not in TIERS:\n                return text, (full + \": \\\"\" + str(key) + \"\\\" must be fast,\"\n                              \" smart or main.\")\n        text = json.dumps({k: data[k] for k in sorted(data)\n                           if data[k] != DEFAULT_TIERS[k]},\n                          separators=(\",\", \":\"))\n        if text == \"{}\":\n            text = \"\"\n    elif name == \"breaker_failures\":\n        if not text.isdigit() or not 1 <= int(text) <= 20:\n            return text, full + \" must be a whole number between 1 and 20.\"\n    elif name == \"breaker_seconds\":\n        if not text.isdigit() or not 10 <= int(text) <= 3600:\n            return text, full + \" must be a whole number between 10 and 3600.\"\n    return text, None\n\n\n# ---------------------------------------------------------------------------\n# admin API\n# ---------------------------------------------------------------------------\n\nbp = Blueprint(\"admin_model_router\", __name__, url_prefix=\"/api/v1/admin/ai\")\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n                os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\")]\n    return any(k for k in accepted if k and _secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _mask(value: str) -> str:\n    value = str(value or \"\")\n    if not value:\n        return \"\"\n    return \"\\u2022\\u2022\\u2022\\u2022\" + value[-4:] if len(value) > 4 \\\n        else \"\\u2022\\u2022\\u2022\\u2022\"\n\n\ndef _labels() -> Dict[str, str]:\n    try:\n        import portal_ai_usage\n\n        return dict(portal_ai_usage.FEATURE_LABELS)\n    except Exception:\n        return {}\n\n\ndef _primary() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.llm_config()\n    except Exception:\n        return {\"base_url\": \"\", \"api_key\": \"\", \"model\": \"\", \"enabled\": False}\n\n\ndef _dedicated() -> List[Dict[str, Any]]:\n    \"\"\"Routes with their own settings group (read-only on the page).\"\"\"\n    labels = _labels()\n    out = []\n    try:\n        import platform_settings\n    except Exception:\n        return out\n    for feature, reader in ((\"assistant\", \"assistant_config\"),\n                            (\"vision\", \"vision_config\")):\n        try:\n            cfg = getattr(platform_settings, reader)()\n            out.append({\"feature\": feature, \"label\": labels.get(feature, feature),\n                        \"model\": str(cfg.get(\"model\") or \"\"),\n                        \"key_source\": str(cfg.get(\"key_source\") or \"none\"),\n                        \"active\": bool(cfg.get(\"active\")),\n                        \"reason\": str(cfg.get(\"reason\") or \"\"),\n                        \"failover\": feature == \"assistant\"})\n        except Exception:\n            continue\n    try:\n        import portal_llm\n\n        stt = portal_llm.stt_runtime()\n        out.append({\"feature\": \"voice_note\", \"label\": labels.get(\"voice_note\", \"voice_note\"),\n                    \"model\": str((stt or {}).get(\"model\") or \"\"),\n                    \"key_source\": \"stt\" if stt else \"none\", \"active\": bool(stt),\n                    \"reason\": \"active\" if stt else \"no_key\", \"failover\": False})\n        embed = portal_llm.embed_runtime()\n        out.append({\"feature\": \"kb_embed\", \"label\": labels.get(\"kb_embed\", \"kb_embed\"),\n                    \"model\": str(embed.get(\"model\") or \"\"),\n                    \"key_source\": str(embed.get(\"key_source\") or \"none\"),\n                    \"active\": bool(embed.get(\"active\")),\n                    \"reason\": str(embed.get(\"reason\") or \"\"), \"failover\": False})\n    except Exception:\n        pass\n    return out\n\n\ndef _usage(days: int) -> Tuple[List[Dict[str, Any]], Optional[str]]:\n    try:\n        import portal_ai_usage\n        import portal_db\n\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                portal_ai_usage._ensure_ddl(cur)\n                cur.execute(\n                    \"SELECT feature, model, COALESCE(route, '') AS route, ok,\"\n                    \" COUNT(*) AS calls, COALESCE(SUM(prompt_tokens), 0) AS pt,\"\n                    \" COALESCE(SUM(completion_tokens), 0) AS ct,\"\n                    \" COALESCE(SUM(latency_ms), 0) AS ms\"\n                    \" FROM \" + portal_db._q(portal_ai_usage.TABLE) +\n                    \" WHERE created_at >= NOW() - (%s * INTERVAL '1 day')\"\n                    \" GROUP BY feature, model, COALESCE(route, ''), ok\",\n                    (int(days),))\n                rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n        return rows or [], None\n    except Exception as error:\n        logger.warning(\"model router usage read failed: %s\", error)\n        return [], \"Usage is temporarily unavailable.\"\n\n\ndef overview(days: int) -> Dict[str, Any]:\n    config = settings()\n    primary = _primary()\n    labels = _labels()\n    try:\n        import platform_settings\n\n        stored = platform_settings.get_group(\"router\")\n    except Exception:\n        stored = {}\n    try:\n        import portal_ai_usage\n\n        prices = portal_ai_usage.prices()\n        estimate = portal_ai_usage.estimate_cost\n    except Exception:\n        prices, estimate = {}, None\n    rows, usage_error = _usage(days)\n\n    per_feature: Dict[str, Dict[str, Any]] = {}\n    per_model: Dict[str, Dict[str, Any]] = {}\n    totals = {\"calls\": 0, \"failed\": 0, \"failovers\": 0, \"routed\": 0,\n              \"tokens\": 0, \"cost_usd\": 0.0 if prices else None}\n    for row in rows:\n        calls = int(row.get(\"calls\") or 0)\n        pt, ct = int(row.get(\"pt\") or 0), int(row.get(\"ct\") or 0)\n        failed = 0 if row.get(\"ok\") else calls\n        route = str(row.get(\"route\") or \"\")\n        cost = estimate(str(row.get(\"model\") or \"\"), pt, ct, prices) \\\n            if estimate and prices else None\n        bucket = per_feature.setdefault(str(row.get(\"feature\") or \"other\"), {\n            \"calls\": 0, \"failed\": 0, \"failovers\": 0, \"tokens\": 0, \"cost_usd\": None})\n        model = per_model.setdefault(str(row.get(\"model\") or \"-\"), {\n            \"model\": str(row.get(\"model\") or \"-\"), \"calls\": 0, \"failed\": 0,\n            \"tokens\": 0, \"latency_ms_total\": 0, \"cost_usd\": None})\n        for target in (bucket, model):\n            target[\"calls\"] += calls\n            target[\"failed\"] += failed\n            target[\"tokens\"] += pt + ct\n            if cost is not None:\n                target[\"cost_usd\"] = round((target[\"cost_usd\"] or 0.0) + cost, 6)\n        model[\"latency_ms_total\"] += int(row.get(\"ms\") or 0)\n        if route == \"failover\":\n            bucket[\"failovers\"] += calls\n            totals[\"failovers\"] += calls\n        if route in (\"fast\", \"smart\", \"failover\"):\n            totals[\"routed\"] += calls\n        totals[\"calls\"] += calls\n        totals[\"failed\"] += failed\n        totals[\"tokens\"] += pt + ct\n        if cost is not None:\n            totals[\"cost_usd\"] = round((totals[\"cost_usd\"] or 0.0) + cost, 6)\n\n    secondary = config[\"secondary\"]\n    has_secondary = bool(secondary[\"api_key\"])\n    main_model = str(primary.get(\"model\") or \"\")\n\n    def effective(tier: str) -> Dict[str, Any]:\n        if tier == \"main\" or config[\"mode\"] != \"on\":\n            return {\"provider\": \"primary\", \"model\": main_model}\n        chosen = config[\"tiers\"][tier]\n        if chosen[\"provider\"] == \"secondary\" and has_secondary:\n            return {\"provider\": \"secondary\",\n                    \"model\": chosen[\"model\"] or secondary[\"model\"] or main_model}\n        return {\"provider\": \"primary\", \"model\": chosen[\"model\"] or main_model}\n\n    routes = []\n    for feature, default_tier in ROUTABLE:\n        tier = tier_for(feature, config)\n        used = per_feature.get(feature, {})\n        routes.append(dict(\n            {\"feature\": feature, \"label\": labels.get(feature, feature),\n             \"tier\": tier, \"default_tier\": default_tier},\n            **effective(tier),\n            calls=int(used.get(\"calls\") or 0), failed=int(used.get(\"failed\") or 0),\n            failovers=int(used.get(\"failovers\") or 0),\n            tokens=int(used.get(\"tokens\") or 0), cost_usd=used.get(\"cost_usd\")))\n\n    warnings = []\n    if not primary.get(\"api_key\"):\n        warnings.append(\"The AI engine has no API key - AI features stay off\"\n                        \" until it is set in Integrations.\")\n    elif not primary.get(\"enabled\"):\n        warnings.append(\"OF_LLM_ENABLED switches the AI engine off on the\"\n                        \" Control Plane.\")\n    for tier in (\"fast\", \"smart\"):\n        if config[\"tiers\"][tier][\"provider\"] == \"secondary\" and not has_secondary:\n            warnings.append(tier.capitalize() + \" tasks are set to the secondary\"\n                            \" provider, but it has no API key - they use the\"\n                            \" AI engine.\")\n    if config[\"mode\"] == \"off\":\n        warnings.append(\"Routing is off - every task uses the AI engine model.\")\n    elif config[\"failover\"] == \"on\" and not has_secondary:\n        warnings.append(\"Failover is on, but there is no secondary provider\"\n                        \" yet - add one to keep AI running during an outage.\")\n    if prices:\n        unpriced = sorted({r[\"model\"] for r in routes\n                           if r[\"model\"] and r[\"model\"].lower() not in prices\n                           and \"default\" not in prices})\n        if unpriced:\n            warnings.append(\"No price saved for \" + \", \".join(unpriced[:5])\n                            + \" - their cost is not counted.\")\n\n    models = sorted(per_model.values(), key=lambda m: -m[\"calls\"])\n    for item in models:\n        item[\"avg_latency_ms\"] = int(item.pop(\"latency_ms_total\")\n                                     / item[\"calls\"]) if item[\"calls\"] else 0\n    return {\n        \"mode\": config[\"mode\"],\n        \"failover\": config[\"failover\"],\n        \"settings\": {\n            \"mode\": str(stored.get(\"mode\") or \"\"),\n            \"failover\": str(stored.get(\"failover\") or \"\"),\n            \"fast_provider\": str(stored.get(\"fast_provider\") or \"\"),\n            \"fast_model\": str(stored.get(\"fast_model\") or \"\"),\n            \"smart_provider\": str(stored.get(\"smart_provider\") or \"\"),\n            \"smart_model\": str(stored.get(\"smart_model\") or \"\"),\n            \"routes\": parse_routes(stored.get(\"routes_json\") or \"\"),\n            \"secondary_base_url\": str(stored.get(\"secondary_base_url\") or \"\"),\n            \"secondary_api_key\": _mask(str(stored.get(\"secondary_api_key\") or \"\")),\n            \"secondary_model\": str(stored.get(\"secondary_model\") or \"\"),\n            \"breaker_failures\": str(stored.get(\"breaker_failures\") or \"\"),\n            \"breaker_seconds\": str(stored.get(\"breaker_seconds\") or \"\"),\n        },\n        \"primary\": {\"configured\": bool(primary.get(\"api_key\")),\n                    \"enabled\": bool(primary.get(\"enabled\")),\n                    \"base_url\": str(primary.get(\"base_url\") or \"\"),\n                    \"model\": main_model},\n        \"secondary\": {\"configured\": has_secondary,\n                      \"base_url\": secondary[\"base_url\"]\n                      or str(primary.get(\"base_url\") or \"\"),\n                      \"model\": secondary[\"model\"],\n                      \"from_env\": has_secondary\n                      and not stored.get(\"secondary_api_key\")},\n        \"tiers\": {tier: effective(tier) for tier in TIERS},\n        \"routes\": routes,\n        \"dedicated\": _dedicated(),\n        \"breaker\": {\"failures\": config[\"breaker_failures\"],\n                    \"seconds\": config[\"breaker_seconds\"],\n                    \"state\": breaker_state()},\n        \"usage\": dict(totals, days=days, models=models[:20], error=usage_error),\n        \"prices_configured\": bool(prices),\n        \"warnings\": warnings,\n    }\n\n\n@bp.get(\"/router\")\ndef get_router():\n    try:\n        days = int(request.args.get(\"days\") or 7)\n    except (TypeError, ValueError):\n        days = 7\n    return jsonify(overview(max(1, min(MAX_DAYS, days)))), 200\n\n\ndef _test_target(name: str) -> Tuple[Optional[Dict[str, Any]], str]:\n    primary = _primary()\n    main = _target(\"primary\", primary.get(\"base_url\"), primary.get(\"api_key\"),\n                   primary.get(\"model\"), \"\")\n    config = settings()\n    if name == \"primary\":\n        return (main if main[\"api_key\"] else None), \\\n            \"The AI engine has no API key yet.\"\n    if name == \"secondary\":\n        secondary = config[\"secondary\"]\n        if not secondary[\"api_key\"]:\n            return None, \"Add the secondary provider's API key first.\"\n        return _target(\"secondary\", secondary[\"base_url\"] or main[\"base_url\"],\n                       secondary[\"api_key\"],\n                       secondary[\"model\"] or main[\"model\"], \"test\"), \"\"\n    feature = {\"fast\": \"intent\", \"smart\": \"brain\"}[name]\n    forced = dict(config, mode=\"on\", failover=\"off\",\n                  routes={feature: name})\n    target = plan(feature, main, forced)[0]\n    if not target[\"api_key\"]:\n        return None, \"The AI engine has no API key yet.\"\n    return target, \"\"\n\n\n@bp.post(\"/router/test\")\ndef post_test():\n    payload = request.get_json(silent=True) or {}\n    name = str(payload.get(\"target\") or \"\").strip().lower()\n    if name not in (\"primary\", \"secondary\", \"fast\", \"smart\"):\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\":\n                                  \"target must be primary, secondary, fast or smart.\"}}), 400\n    target, why = _test_target(name)\n    if target is None:\n        return jsonify({\"error\": {\"code\": \"not_configured\", \"message\": why}}), 409\n    import portal_llm\n\n    body = {\"model\": target[\"model\"], \"temperature\": 0, \"max_tokens\": 16,\n            \"response_format\": {\"type\": \"json_object\"},\n            \"messages\": [{\"role\": \"system\", \"content\":\n                          \"Health check. Reply with the JSON object {\\\"ok\\\": true}.\"},\n                         {\"role\": \"user\", \"content\": \"ping\"}]}\n    started = time.time()\n    data, error = portal_llm._post_detail(\n        target[\"base_url\"] + \"/chat/completions\",\n        {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n         \"Content-Type\": \"application/json\"}, body, TEST_TIMEOUT_SECONDS)\n    latency = int((time.time() - started) * 1000)\n    ok = False\n    if isinstance(data, dict):\n        try:\n            ok = isinstance(json.loads(data[\"choices\"][0][\"message\"][\"content\"]), dict)\n        except Exception:\n            ok = False\n        if not ok:\n            error = error or \"The model answered, but not with JSON.\"\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    try:\n        import portal_ai_usage\n\n        usage = usage if isinstance(usage, dict) else {}\n        portal_ai_usage.record(0, \"other\", target[\"model\"],\n                               int(usage.get(\"prompt_tokens\") or 0),\n                               int(usage.get(\"completion_tokens\") or 0),\n                               latency, ok, route=\"test\")\n    except Exception:\n        pass\n    return jsonify({\"ok\": ok, \"target\": name, \"provider\": target[\"provider\"],\n                    \"model\": target[\"model\"], \"latency_ms\": latency,\n                    \"error\": \"\" if ok else (error or \"No answer.\")[:200]}), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_model_router.py", "def failover_for(", true,
    "\"\"\"Model Router (\u00a7229) - which model answers which AI task, with failover.\n\nTwo providers:\n- primary   = the AI engine (Admin > Integrations > AI engine / OF_LLM_*),\n- secondary = an optional second OpenAI-compatible provider (another\n  vendor, or a second key on the same one).\nTwo tiers on top of them:\n- fast  = light classification work (intent, sentiment, workflow branch),\n- smart = customer-facing writing (brain replies, negotiation, copy, ...).\nEach tier picks a provider and a model; every routable feature picks a\ntier (fast | smart | main), with sensible defaults. ``main`` is the AI\nengine exactly as before.\n\nFailover: when the chosen provider does not answer (transport error,\nHTTP error, timeout) the call is retried once on the other provider. A\nprovider answering with unusable JSON is NOT failed over (that is the\nmodel, not the provider). A small in-process circuit breaker skips a\nprovider after N consecutive failures for S seconds when the other one\ncan serve the call.\n\nZero configuration = today's behaviour: blank tier models resolve to the\nAI engine's model on the AI engine, and failover needs a secondary key.\nDedicated routes keep their own settings (assistant, image understanding,\nvoice notes, knowledge embeddings) and are shown on the admin page.\n\nStandard library only (portal_llm imports this on the hot path); config\nis read through platform_settings' 30-second cache with env fallbacks.\nAdmin API (service key): GET /api/v1/admin/ai/router, POST .../test.\nSaving goes through the existing PUT /api/v1/admin/providers (group\n``router``), validated by clean_value() below.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport re\nimport secrets as _secrets\nimport threading\nimport time\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nlogger = logging.getLogger(\"omniflow.model-router\")\n\nMODES = (\"on\", \"off\")\nPROVIDERS = (\"primary\", \"secondary\")\nTIERS = (\"fast\", \"smart\", \"main\")\n\n#: feature -> default tier. Only features that call portal_llm.chat_json.\nROUTABLE: Tuple[Tuple[str, str], ...] = (\n    (\"brain\", \"smart\"),\n    (\"voice_call\", \"smart\"),\n    (\"negotiation\", \"smart\"),\n    (\"copy\", \"smart\"),\n    (\"bi_narrative\", \"smart\"),\n    (\"site_analyzer\", \"smart\"),\n    (\"ai_quality_label\", \"smart\"),\n    (\"workflow\", \"fast\"),\n    (\"intent\", \"fast\"),\n    (\"sentiment\", \"fast\"),\n    (\"other\", \"main\"),\n)\nDEFAULT_TIERS = dict(ROUTABLE)\n\nTEST_TIMEOUT_SECONDS = float(os.environ.get(\"OF_ROUTER_TEST_TIMEOUT\", \"12\") or 12)\nMAX_MODEL_CHARS = 120\nMAX_DAYS = 90\n_MODEL_RE = re.compile(r\"^[A-Za-z0-9._:/@+\\-]{1,120}$\")\n_URL_RE = re.compile(r\"^https?://[^\\s?#]+$\")\n\n\ndef _env(name: str, default: str = \"\") -> str:\n    return os.environ.get(name, default).strip()\n\n\ndef _setting(name: str, env: str, default: str = \"\") -> str:\n    \"\"\"Admin panel first (cached), env fallback, then default.\"\"\"\n    value = \"\"\n    try:\n        import platform_settings\n\n        value = platform_settings._cached(\"router.\" + name)\n    except Exception:\n        value = \"\"\n    return value or _env(env, default)\n\n\ndef _bounded(raw: str, default: int, low: int, high: int) -> int:\n    try:\n        value = int(str(raw or \"\").strip() or default)\n    except (TypeError, ValueError):\n        value = default\n    return max(low, min(high, value))\n\n\ndef parse_routes(raw: Any) -> Dict[str, str]:\n    \"\"\"routes_json -> {feature: tier}; unknown features / tiers dropped.\"\"\"\n    try:\n        data = json.loads(raw) if isinstance(raw, str) and raw.strip() else raw\n    except Exception:\n        return {}\n    if not isinstance(data, dict):\n        return {}\n    return {str(k): str(v) for k, v in data.items()\n            if str(k) in DEFAULT_TIERS and str(v) in TIERS}\n\n\ndef settings() -> Dict[str, Any]:\n    \"\"\"Effective router config (fail-soft, never raises).\"\"\"\n    mode = _setting(\"mode\", \"OF_ROUTER_MODE\", \"on\").lower()\n    failover = _setting(\"failover\", \"OF_ROUTER_FAILOVER\", \"on\").lower()\n    tiers = {}\n    for tier in (\"fast\", \"smart\"):\n        provider = _setting(tier + \"_provider\",\n                            \"OF_ROUTER_\" + tier.upper() + \"_PROVIDER\",\n                            \"primary\").lower()\n        tiers[tier] = {\n            \"provider\": provider if provider in PROVIDERS else \"primary\",\n            \"model\": _setting(tier + \"_model\",\n                              \"OF_ROUTER_\" + tier.upper() + \"_MODEL\"),\n        }\n    return {\n        \"mode\": mode if mode in MODES else \"on\",\n        \"failover\": failover if failover in MODES else \"on\",\n        \"tiers\": tiers,\n        \"routes\": parse_routes(_setting(\"routes_json\", \"OF_ROUTER_ROUTES_JSON\")),\n        \"secondary\": {\n            \"base_url\": _setting(\"secondary_base_url\",\n                                 \"OF_ROUTER_SECONDARY_BASE_URL\").rstrip(\"/\"),\n            \"api_key\": _setting(\"secondary_api_key\",\n                                \"OF_ROUTER_SECONDARY_API_KEY\"),\n            \"model\": _setting(\"secondary_model\", \"OF_ROUTER_SECONDARY_MODEL\"),\n        },\n        \"breaker_failures\": _bounded(\n            _setting(\"breaker_failures\", \"OF_ROUTER_BREAKER_FAILURES\"), 3, 1, 20),\n        \"breaker_seconds\": _bounded(\n            _setting(\"breaker_seconds\", \"OF_ROUTER_BREAKER_SECONDS\"), 60, 10, 3600),\n    }\n\n\ndef tier_for(feature: str, config: Optional[Dict[str, Any]] = None) -> str:\n    config = config if config is not None else settings()\n    feature = feature if feature in DEFAULT_TIERS else \"other\"\n    return config[\"routes\"].get(feature) or DEFAULT_TIERS[feature]\n\n\n# ---------------------------------------------------------------------------\n# circuit breaker (per process; serverless instances each keep their own)\n# ---------------------------------------------------------------------------\n\n_LOCK = threading.Lock()\n_BREAKER: Dict[str, Dict[str, Any]] = {}\n\n\ndef note(provider: str, ok: bool, config: Optional[Dict[str, Any]] = None) -> None:\n    \"\"\"Record one provider outcome; opens the breaker after N failures.\"\"\"\n    if provider not in PROVIDERS:\n        return\n    try:\n        config = config if config is not None else settings()\n        with _LOCK:\n            state = _BREAKER.setdefault(provider, {\n                \"failures\": 0, \"open_until\": 0.0, \"last_failure_at\": 0.0})\n            if ok:\n                state[\"failures\"] = 0\n                state[\"open_until\"] = 0.0\n                return\n            state[\"failures\"] += 1\n            state[\"last_failure_at\"] = time.time()\n            if state[\"failures\"] >= config[\"breaker_failures\"]:\n                state[\"open_until\"] = time.time() + config[\"breaker_seconds\"]\n                logger.warning(\"model router: %s provider paused for %ss after\"\n                               \" %s failures\", provider,\n                               config[\"breaker_seconds\"], state[\"failures\"])\n    except Exception:\n        pass\n\n\ndef is_open(provider: str) -> bool:\n    with _LOCK:\n        state = _BREAKER.get(provider)\n        return bool(state and state[\"open_until\"] > time.time())\n\n\ndef breaker_state() -> Dict[str, Dict[str, Any]]:\n    now = time.time()\n    out = {}\n    with _LOCK:\n        for provider in PROVIDERS:\n            state = _BREAKER.get(provider) or {}\n            until = float(state.get(\"open_until\") or 0.0)\n            out[provider] = {\n                \"failures\": int(state.get(\"failures\") or 0),\n                \"paused\": until > now,\n                \"paused_seconds_left\": max(0, int(until - now)),\n            }\n    return out\n\n\ndef reset_breaker() -> None:\n    with _LOCK:\n        _BREAKER.clear()\n\n\n# ---------------------------------------------------------------------------\n# planning (portal_llm calls this for every chat_json)\n# ---------------------------------------------------------------------------\n\ndef _target(provider: str, base_url: str, api_key: str, model: str,\n            route: str) -> Dict[str, Any]:\n    return {\"provider\": provider, \"base_url\": str(base_url or \"\").rstrip(\"/\"),\n            \"api_key\": str(api_key or \"\"), \"model\": str(model or \"\"),\n            \"route\": route}\n\n\ndef plan(feature: str, primary: Dict[str, Any],\n         config: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:\n    \"\"\"Ordered targets for one call: [chosen] or [chosen, failover].\n\n    ``primary`` = the AI engine runtime (base_url, api_key, model).\n    ``route`` on a target is \"\" when it is exactly the AI engine (the\n    ledger then looks like before), else fast | smart | failover.\n    \"\"\"\n    main = _target(\"primary\", primary.get(\"base_url\"), primary.get(\"api_key\"),\n                   primary.get(\"model\"), \"\")\n    config = config if config is not None else settings()\n    if config[\"mode\"] != \"on\":\n        return [main]\n    secondary = config[\"secondary\"]\n    has_secondary = bool(secondary[\"api_key\"])\n    secondary_base = secondary[\"base_url\"] or main[\"base_url\"]\n    tier = tier_for(feature, config)\n    first = main\n    if tier in (\"fast\", \"smart\"):\n        chosen = config[\"tiers\"][tier]\n        if chosen[\"provider\"] == \"secondary\" and has_secondary:\n            first = _target(\"secondary\", secondary_base, secondary[\"api_key\"],\n                            chosen[\"model\"] or secondary[\"model\"]\n                            or main[\"model\"], tier)\n        elif chosen[\"model\"] and chosen[\"model\"] != main[\"model\"]:\n            first = _target(\"primary\", main[\"base_url\"], main[\"api_key\"],\n                            chosen[\"model\"], tier)\n    targets = [first]\n    if config[\"failover\"] == \"on\" and has_secondary:\n        if first[\"provider\"] == \"primary\":\n            second = _target(\"secondary\", secondary_base, secondary[\"api_key\"],\n                             secondary[\"model\"] or first[\"model\"], \"failover\")\n        else:\n            second = dict(main, route=\"failover\")\n        if is_open(first[\"provider\"]) and not is_open(second[\"provider\"]):\n            return [second]\n        targets.append(second)\n    return targets\n\n\ndef failover_for(model: str, config: Optional[Dict[str, Any]] = None\n                 ) -> Optional[Dict[str, Any]]:\n    \"\"\"The secondary provider as a failover target for a dedicated route\n    (the owner assistant), or None when failover is off / not set up.\"\"\"\n    try:\n        config = config if config is not None else settings()\n    except Exception:\n        return None\n    secondary = config[\"secondary\"]\n    if config[\"mode\"] != \"on\" or config[\"failover\"] != \"on\" \\\n            or not secondary[\"api_key\"]:\n        return None\n    base = secondary[\"base_url\"]\n    if not base:\n        try:\n            import platform_settings\n\n            base = platform_settings.llm_config().get(\"base_url\") or \"\"\n        except Exception:\n            base = \"\"\n    if not base:\n        return None\n    return _target(\"secondary\", base, secondary[\"api_key\"],\n                   secondary[\"model\"] or model, \"failover\")\n\n\n# ---------------------------------------------------------------------------\n# admin validation (called by admin_providers for group \"router\")\n# ---------------------------------------------------------------------------\n\ndef clean_value(name: str, text: str) -> Tuple[str, Optional[str]]:\n    \"\"\"Normalise one router setting; (value, None) or (value, error).\"\"\"\n    text = str(text or \"\").strip()\n    full = \"router.\" + name\n    if not text:\n        return \"\", None\n    if name in (\"mode\", \"failover\"):\n        text = text.lower()\n        if text not in MODES:\n            return text, full + \" must be on or off.\"\n    elif name in (\"fast_provider\", \"smart_provider\"):\n        text = text.lower()\n        if text not in PROVIDERS:\n            return text, full + \" must be primary or secondary.\"\n    elif name in (\"fast_model\", \"smart_model\", \"secondary_model\"):\n        if not _MODEL_RE.match(text):\n            return text, (full + \" must be a model name without spaces (\"\n                          + str(MAX_MODEL_CHARS) + \" characters max).\")\n    elif name == \"secondary_base_url\":\n        text = text.rstrip(\"/\")\n        if len(text) > 300 or not _URL_RE.match(text):\n            return text, (full + \" must be an http(s) address such as\"\n                          \" https://api.groq.com/openai/v1 (no query).\")\n    elif name == \"secondary_api_key\":\n        if len(text) > 400 or any(ch.isspace() for ch in text):\n            return text, full + \" looks wrong (no spaces, 400 characters max).\"\n    elif name == \"routes_json\":\n        try:\n            data = json.loads(text)\n        except Exception:\n            return text, full + \" must be a JSON object.\"\n        if not isinstance(data, dict):\n            return text, full + \" must be a JSON object.\"\n        for key, value in data.items():\n            if key not in DEFAULT_TIERS:\n                return text, full + \": unknown task \\\"\" + str(key)[:40] + \"\\\".\"\n            if value not in TIERS:\n                return text, (full + \": \\\"\" + str(key) + \"\\\" must be fast,\"\n                              \" smart or main.\")\n        text = json.dumps({k: data[k] for k in sorted(data)\n                           if data[k] != DEFAULT_TIERS[k]},\n                          separators=(\",\", \":\"))\n        if text == \"{}\":\n            text = \"\"\n    elif name == \"breaker_failures\":\n        if not text.isdigit() or not 1 <= int(text) <= 20:\n            return text, full + \" must be a whole number between 1 and 20.\"\n    elif name == \"breaker_seconds\":\n        if not text.isdigit() or not 10 <= int(text) <= 3600:\n            return text, full + \" must be a whole number between 10 and 3600.\"\n    return text, None\n\n\n# ---------------------------------------------------------------------------\n# admin API\n# ---------------------------------------------------------------------------\n\nbp = Blueprint(\"admin_model_router\", __name__, url_prefix=\"/api/v1/admin/ai\")\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n                os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\")]\n    return any(k for k in accepted if k and _secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _mask(value: str) -> str:\n    value = str(value or \"\")\n    if not value:\n        return \"\"\n    return \"\\u2022\\u2022\\u2022\\u2022\" + value[-4:] if len(value) > 4 \\\n        else \"\\u2022\\u2022\\u2022\\u2022\"\n\n\ndef _labels() -> Dict[str, str]:\n    try:\n        import portal_ai_usage\n\n        return dict(portal_ai_usage.FEATURE_LABELS)\n    except Exception:\n        return {}\n\n\ndef _primary() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.llm_config()\n    except Exception:\n        return {\"base_url\": \"\", \"api_key\": \"\", \"model\": \"\", \"enabled\": False}\n\n\ndef _dedicated() -> List[Dict[str, Any]]:\n    \"\"\"Routes with their own settings group (read-only on the page).\"\"\"\n    labels = _labels()\n    out = []\n    try:\n        import platform_settings\n    except Exception:\n        return out\n    for feature, reader in ((\"assistant\", \"assistant_config\"),\n                            (\"vision\", \"vision_config\")):\n        try:\n            cfg = getattr(platform_settings, reader)()\n            out.append({\"feature\": feature, \"label\": labels.get(feature, feature),\n                        \"model\": str(cfg.get(\"model\") or \"\"),\n                        \"key_source\": str(cfg.get(\"key_source\") or \"none\"),\n                        \"active\": bool(cfg.get(\"active\")),\n                        \"reason\": str(cfg.get(\"reason\") or \"\"),\n                        \"failover\": feature == \"assistant\"})\n        except Exception:\n            continue\n    try:\n        import portal_llm\n\n        stt = portal_llm.stt_runtime()\n        out.append({\"feature\": \"voice_note\", \"label\": labels.get(\"voice_note\", \"voice_note\"),\n                    \"model\": str((stt or {}).get(\"model\") or \"\"),\n                    \"key_source\": \"stt\" if stt else \"none\", \"active\": bool(stt),\n                    \"reason\": \"active\" if stt else \"no_key\", \"failover\": False})\n        embed = portal_llm.embed_runtime()\n        out.append({\"feature\": \"kb_embed\", \"label\": labels.get(\"kb_embed\", \"kb_embed\"),\n                    \"model\": str(embed.get(\"model\") or \"\"),\n                    \"key_source\": str(embed.get(\"key_source\") or \"none\"),\n                    \"active\": bool(embed.get(\"active\")),\n                    \"reason\": str(embed.get(\"reason\") or \"\"), \"failover\": False})\n    except Exception:\n        pass\n    return out\n\n\ndef _usage(days: int) -> Tuple[List[Dict[str, Any]], Optional[str]]:\n    try:\n        import portal_ai_usage\n        import portal_db\n\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                portal_ai_usage._ensure_ddl(cur)\n                cur.execute(\n                    \"SELECT feature, model, COALESCE(route, '') AS route, ok,\"\n                    \" COUNT(*) AS calls, COALESCE(SUM(prompt_tokens), 0) AS pt,\"\n                    \" COALESCE(SUM(completion_tokens), 0) AS ct,\"\n                    \" COALESCE(SUM(latency_ms), 0) AS ms\"\n                    \" FROM \" + portal_db._q(portal_ai_usage.TABLE) +\n                    \" WHERE created_at >= NOW() - (%s * INTERVAL '1 day')\"\n                    \" GROUP BY feature, model, COALESCE(route, ''), ok\",\n                    (int(days),))\n                rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n        return rows or [], None\n    except Exception as error:\n        logger.warning(\"model router usage read failed: %s\", error)\n        return [], \"Usage is temporarily unavailable.\"\n\n\ndef overview(days: int) -> Dict[str, Any]:\n    config = settings()\n    primary = _primary()\n    labels = _labels()\n    try:\n        import platform_settings\n\n        stored = platform_settings.get_group(\"router\")\n    except Exception:\n        stored = {}\n    try:\n        import portal_ai_usage\n\n        prices = portal_ai_usage.prices()\n        estimate = portal_ai_usage.estimate_cost\n    except Exception:\n        prices, estimate = {}, None\n    rows, usage_error = _usage(days)\n\n    per_feature: Dict[str, Dict[str, Any]] = {}\n    per_model: Dict[str, Dict[str, Any]] = {}\n    totals = {\"calls\": 0, \"failed\": 0, \"failovers\": 0, \"routed\": 0,\n              \"tokens\": 0, \"cost_usd\": 0.0 if prices else None}\n    for row in rows:\n        calls = int(row.get(\"calls\") or 0)\n        pt, ct = int(row.get(\"pt\") or 0), int(row.get(\"ct\") or 0)\n        failed = 0 if row.get(\"ok\") else calls\n        route = str(row.get(\"route\") or \"\")\n        cost = estimate(str(row.get(\"model\") or \"\"), pt, ct, prices) \\\n            if estimate and prices else None\n        bucket = per_feature.setdefault(str(row.get(\"feature\") or \"other\"), {\n            \"calls\": 0, \"failed\": 0, \"failovers\": 0, \"tokens\": 0, \"cost_usd\": None})\n        model = per_model.setdefault(str(row.get(\"model\") or \"-\"), {\n            \"model\": str(row.get(\"model\") or \"-\"), \"calls\": 0, \"failed\": 0,\n            \"tokens\": 0, \"latency_ms_total\": 0, \"cost_usd\": None})\n        for target in (bucket, model):\n            target[\"calls\"] += calls\n            target[\"failed\"] += failed\n            target[\"tokens\"] += pt + ct\n            if cost is not None:\n                target[\"cost_usd\"] = round((target[\"cost_usd\"] or 0.0) + cost, 6)\n        model[\"latency_ms_total\"] += int(row.get(\"ms\") or 0)\n        if route == \"failover\":\n            bucket[\"failovers\"] += calls\n            totals[\"failovers\"] += calls\n        if route in (\"fast\", \"smart\", \"failover\"):\n            totals[\"routed\"] += calls\n        totals[\"calls\"] += calls\n        totals[\"failed\"] += failed\n        totals[\"tokens\"] += pt + ct\n        if cost is not None:\n            totals[\"cost_usd\"] = round((totals[\"cost_usd\"] or 0.0) + cost, 6)\n\n    secondary = config[\"secondary\"]\n    has_secondary = bool(secondary[\"api_key\"])\n    main_model = str(primary.get(\"model\") or \"\")\n\n    def effective(tier: str) -> Dict[str, Any]:\n        if tier == \"main\" or config[\"mode\"] != \"on\":\n            return {\"provider\": \"primary\", \"model\": main_model}\n        chosen = config[\"tiers\"][tier]\n        if chosen[\"provider\"] == \"secondary\" and has_secondary:\n            return {\"provider\": \"secondary\",\n                    \"model\": chosen[\"model\"] or secondary[\"model\"] or main_model}\n        return {\"provider\": \"primary\", \"model\": chosen[\"model\"] or main_model}\n\n    routes = []\n    for feature, default_tier in ROUTABLE:\n        tier = tier_for(feature, config)\n        used = per_feature.get(feature, {})\n        routes.append(dict(\n            {\"feature\": feature, \"label\": labels.get(feature, feature),\n             \"tier\": tier, \"default_tier\": default_tier},\n            **effective(tier),\n            calls=int(used.get(\"calls\") or 0), failed=int(used.get(\"failed\") or 0),\n            failovers=int(used.get(\"failovers\") or 0),\n            tokens=int(used.get(\"tokens\") or 0), cost_usd=used.get(\"cost_usd\")))\n\n    warnings = []\n    if not primary.get(\"api_key\"):\n        warnings.append(\"The AI engine has no API key - AI features stay off\"\n                        \" until it is set in Integrations.\")\n    elif not primary.get(\"enabled\"):\n        warnings.append(\"OF_LLM_ENABLED switches the AI engine off on the\"\n                        \" Control Plane.\")\n    for tier in (\"fast\", \"smart\"):\n        if config[\"tiers\"][tier][\"provider\"] == \"secondary\" and not has_secondary:\n            warnings.append(tier.capitalize() + \" tasks are set to the secondary\"\n                            \" provider, but it has no API key - they use the\"\n                            \" AI engine.\")\n    if config[\"mode\"] == \"off\":\n        warnings.append(\"Routing is off - every task uses the AI engine model.\")\n    elif config[\"failover\"] == \"on\" and not has_secondary:\n        warnings.append(\"Failover is on, but there is no secondary provider\"\n                        \" yet - add one to keep AI running during an outage.\")\n    if prices:\n        unpriced = sorted({r[\"model\"] for r in routes\n                           if r[\"model\"] and r[\"model\"].lower() not in prices\n                           and \"default\" not in prices})\n        if unpriced:\n            warnings.append(\"No price saved for \" + \", \".join(unpriced[:5])\n                            + \" - their cost is not counted.\")\n\n    models = sorted(per_model.values(), key=lambda m: -m[\"calls\"])\n    for item in models:\n        item[\"avg_latency_ms\"] = int(item.pop(\"latency_ms_total\")\n                                     / item[\"calls\"]) if item[\"calls\"] else 0\n    return {\n        \"mode\": config[\"mode\"],\n        \"failover\": config[\"failover\"],\n        \"settings\": {\n            \"mode\": str(stored.get(\"mode\") or \"\"),\n            \"failover\": str(stored.get(\"failover\") or \"\"),\n            \"fast_provider\": str(stored.get(\"fast_provider\") or \"\"),\n            \"fast_model\": str(stored.get(\"fast_model\") or \"\"),\n            \"smart_provider\": str(stored.get(\"smart_provider\") or \"\"),\n            \"smart_model\": str(stored.get(\"smart_model\") or \"\"),\n            \"routes\": parse_routes(stored.get(\"routes_json\") or \"\"),\n            \"secondary_base_url\": str(stored.get(\"secondary_base_url\") or \"\"),\n            \"secondary_api_key\": _mask(str(stored.get(\"secondary_api_key\") or \"\")),\n            \"secondary_model\": str(stored.get(\"secondary_model\") or \"\"),\n            \"breaker_failures\": str(stored.get(\"breaker_failures\") or \"\"),\n            \"breaker_seconds\": str(stored.get(\"breaker_seconds\") or \"\"),\n        },\n        \"primary\": {\"configured\": bool(primary.get(\"api_key\")),\n                    \"enabled\": bool(primary.get(\"enabled\")),\n                    \"base_url\": str(primary.get(\"base_url\") or \"\"),\n                    \"model\": main_model},\n        \"secondary\": {\"configured\": has_secondary,\n                      \"base_url\": secondary[\"base_url\"]\n                      or str(primary.get(\"base_url\") or \"\"),\n                      \"model\": secondary[\"model\"],\n                      \"from_env\": has_secondary\n                      and not stored.get(\"secondary_api_key\")},\n        \"tiers\": {tier: effective(tier) for tier in TIERS},\n        \"routes\": routes,\n        \"dedicated\": _dedicated(),\n        \"breaker\": {\"failures\": config[\"breaker_failures\"],\n                    \"seconds\": config[\"breaker_seconds\"],\n                    \"state\": breaker_state()},\n        \"usage\": dict(totals, days=days, models=models[:20], error=usage_error),\n        \"prices_configured\": bool(prices),\n        \"warnings\": warnings,\n    }\n\n\n@bp.get(\"/router\")\ndef get_router():\n    try:\n        days = int(request.args.get(\"days\") or 7)\n    except (TypeError, ValueError):\n        days = 7\n    return jsonify(overview(max(1, min(MAX_DAYS, days)))), 200\n\n\ndef _test_target(name: str) -> Tuple[Optional[Dict[str, Any]], str]:\n    primary = _primary()\n    main = _target(\"primary\", primary.get(\"base_url\"), primary.get(\"api_key\"),\n                   primary.get(\"model\"), \"\")\n    config = settings()\n    if name == \"primary\":\n        return (main if main[\"api_key\"] else None), \\\n            \"The AI engine has no API key yet.\"\n    if name == \"secondary\":\n        secondary = config[\"secondary\"]\n        if not secondary[\"api_key\"]:\n            return None, \"Add the secondary provider's API key first.\"\n        return _target(\"secondary\", secondary[\"base_url\"] or main[\"base_url\"],\n                       secondary[\"api_key\"],\n                       secondary[\"model\"] or main[\"model\"], \"test\"), \"\"\n    feature = {\"fast\": \"intent\", \"smart\": \"brain\"}[name]\n    forced = dict(config, mode=\"on\", failover=\"off\",\n                  routes={feature: name})\n    target = plan(feature, main, forced)[0]\n    if not target[\"api_key\"]:\n        return None, \"The AI engine has no API key yet.\"\n    return target, \"\"\n\n\n@bp.post(\"/router/test\")\ndef post_test():\n    payload = request.get_json(silent=True) or {}\n    name = str(payload.get(\"target\") or \"\").strip().lower()\n    if name not in (\"primary\", \"secondary\", \"fast\", \"smart\"):\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\":\n                                  \"target must be primary, secondary, fast or smart.\"}}), 400\n    target, why = _test_target(name)\n    if target is None:\n        return jsonify({\"error\": {\"code\": \"not_configured\", \"message\": why}}), 409\n    import portal_llm\n\n    body = {\"model\": target[\"model\"], \"temperature\": 0, \"max_tokens\": 16,\n            \"response_format\": {\"type\": \"json_object\"},\n            \"messages\": [{\"role\": \"system\", \"content\":\n                          \"Health check. Reply with the JSON object {\\\"ok\\\": true}.\"},\n                         {\"role\": \"user\", \"content\": \"ping\"}]}\n    started = time.time()\n    data, error = portal_llm._post_detail(\n        target[\"base_url\"] + \"/chat/completions\",\n        {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n         \"Content-Type\": \"application/json\"}, body, TEST_TIMEOUT_SECONDS)\n    latency = int((time.time() - started) * 1000)\n    ok = False\n    if isinstance(data, dict):\n        try:\n            ok = isinstance(json.loads(data[\"choices\"][0][\"message\"][\"content\"]), dict)\n        except Exception:\n            ok = False\n        if not ok:\n            error = error or \"The model answered, but not with JSON.\"\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    try:\n        import portal_ai_usage\n\n        usage = usage if isinstance(usage, dict) else {}\n        portal_ai_usage.record(0, \"other\", target[\"model\"],\n                               int(usage.get(\"prompt_tokens\") or 0),\n                               int(usage.get(\"completion_tokens\") or 0),\n                               latency, ok, route=\"test\")\n    except Exception:\n        pass\n    return jsonify({\"ok\": ok, \"target\": name, \"provider\": target[\"provider\"],\n                    \"model\": target[\"model\"], \"latency_ms\": latency,\n                    \"error\": \"\" if ok else (error or \"No answer.\")[:200]}), 200\n");
writeNewRepair("omniflow-backend-patch/portal_llm.py", "def _route_targets(", false,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float,\n                  route: str = \"\") -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\n    ``route`` (\u00a7229) is only passed when the model router changed the\n    target (fast | smart | failover); plain AI-engine calls look as before.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        extra = {\"route\": route} if route else {}\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model,\n            int(usage.get(\"prompt_tokens\") or 0),\n            int(usage.get(\"completion_tokens\") or 0),\n            int((time.time() - started) * 1000), ok, cur=cur,\n            agent_id=agent_id, **extra)\n    except Exception:\n        pass\n\n\ndef _record_routed(model: str, usage: Any, ok: bool, started: float,\n                   route: str) -> None:\n    # tests replace _record_usage with a 4-argument stub: keep that shape\n    # for every call the router did not change\n    if route:\n        _record_usage(model, usage, ok, started, route=route)\n    else:\n        _record_usage(model, usage, ok, started)\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any],\n                    timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(\n                request, timeout=timeout or TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef _route_targets(runtime: Dict[str, Any]) -> List[Dict[str, Any]]:\n    \"\"\"Model router (\u00a7229): [chosen target] or [chosen, failover]. Falls\n    back to the AI engine alone when the router is missing or broken.\"\"\"\n    main = {\"provider\": \"primary\",\n            \"base_url\": str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\"),\n            \"api_key\": str(runtime.get(\"api_key\") or \"\"),\n            \"model\": str(runtime.get(\"model\") or MODEL), \"route\": \"\"}\n    try:\n        import portal_model_router\n\n        return portal_model_router.plan(current_scope()[0], main) or [main]\n    except Exception:\n        return [main]\n\n\ndef _note_provider(target: Dict[str, Any], ok: bool) -> None:\n    try:\n        import portal_model_router\n\n        portal_model_router.note(target.get(\"provider\", \"\"), ok)\n    except Exception:\n        pass\n\n\ndef chat_json(system: str, user: str, max_tokens: int = 120,\n              timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\n    ``timeout`` overrides OF_LLM_TIMEOUT_SECONDS for one long answer\n    (e.g. the website analyzer's extraction). The model router picks the\n    model for the current usage scope and fails over to the secondary\n    provider when the chosen one does not answer.\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    for target in _route_targets(runtime):\n        payload = {\n            \"model\": target[\"model\"] or MODEL,\n            \"messages\": [\n                {\"role\": \"system\", \"content\": system},\n                {\"role\": \"user\", \"content\": user},\n            ],\n            \"temperature\": 0,\n            \"max_tokens\": max_tokens,\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\n            \"Authorization\": \"Bearer \" + str(target[\"api_key\"]),\n            \"Content-Type\": \"application/json\",\n        }\n        base = str(target[\"base_url\"] or BASE_URL).rstrip(\"/\")\n        model = str(payload[\"model\"])\n        route = str(target.get(\"route\") or \"\")\n        started = time.time()\n        last_usage = None\n        answered = False\n        for _ in range(ATTEMPTS):\n            if timeout:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload, timeout=timeout)\n            else:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload)\n            if not data:\n                continue\n            answered = True\n            last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n            try:\n                content = data[\"choices\"][0][\"message\"][\"content\"]\n                parsed = json.loads(content)\n            except Exception:\n                continue\n            if isinstance(parsed, dict):\n                _note_provider(target, True)\n                _record_routed(model, last_usage, True, started, route)\n                return parsed\n        _note_provider(target, answered)\n        _record_routed(model, last_usage, False, started, route)\n        if answered:\n            # the provider is up; an unusable answer is not failed over\n            return None\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n\n# ---------------------------------------------------------------------------\n# D5 media understanding: speech-to-text + image understanding. Same\n# contract as chat/embeddings: gated (kill switch / daily cap), one ledger\n# row per call under the caller's usage_scope, (result, error), never raises.\n# ---------------------------------------------------------------------------\n\nSTT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_STT_TIMEOUT_SECONDS\", \"20\") or 20)\nVISION_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_VISION_TIMEOUT_SECONDS\", \"15\") or 15)\nVISION_MAX_TOKENS = max(64, min(1024, int(\n    os.environ.get(\"OF_VISION_MAX_TOKENS\", \"300\") or 300)))\n\n\ndef stt_runtime() -> Optional[Dict[str, str]]:\n    \"\"\"Resolved speech-to-text endpoint (portal_media owns the defaults:\n    admin panel -> env -> OpenAI whisper). None when no key is saved.\"\"\"\n    try:\n        import portal_media\n\n        resolved = portal_media._stt_config()\n    except Exception:\n        resolved = None\n    if not resolved:\n        return None\n    base, key, model = resolved\n    return {\"base_url\": base, \"api_key\": key, \"model\": model}\n\n\ndef vision_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.vision_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef transcribe_audio(data: bytes, mime: str, filename: str = \"voice-note\",\n                     language: str = \"\", timeout: Optional[float] = None,\n                     runtime: Optional[Dict[str, str]] = None\n                     ) -> Tuple[Optional[str], str]:\n    \"\"\"Speech-to-text via the OpenAI-compatible /audio/transcriptions\n    endpoint (Whisper, Groq, ...). Returns (text, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty audio\"\n    config = runtime or stt_runtime()\n    if not config or not config.get(\"api_key\"):\n        return None, \"speech-to-text not configured\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    try:\n        import portal_media\n\n        fields = {\"model\": str(config.get(\"model\") or \"\")}\n        if language:\n            fields[\"language\"] = str(language)[:8]\n        body, boundary = portal_media._multipart_body(\n            fields, \"file\", str(filename or \"voice-note\")[:80],\n            str(mime or \"audio/ogg\")[:80], data)\n    except Exception as error:\n        return None, \"could not build the upload: \" + str(error)[:80]\n    model = str(config.get(\"model\") or \"\")\n    started = time.time()\n    try:\n        request = urllib.request.Request(\n            str(config[\"base_url\"]).rstrip(\"/\") + \"/audio/transcriptions\",\n            data=body, method=\"POST\")\n        request.add_header(\"Content-Type\",\n                           \"multipart/form-data; boundary=\" + boundary)\n        request.add_header(\"Authorization\", \"Bearer \" + str(config[\"api_key\"]))\n        with urllib.request.urlopen(\n                request, timeout=float(timeout or STT_TIMEOUT_SECONDS)) as resp:\n            parsed = json.loads(resp.read().decode(\"utf-8\", \"replace\"))\n    except urllib.error.HTTPError as error:\n        _record_usage(model, None, False, started)\n        return None, \"HTTP \" + str(error.code)\n    except Exception as error:\n        _record_usage(model, None, False, started)\n        return None, type(error).__name__ + \": \" + str(error)[:100]\n    text = str((parsed or {}).get(\"text\") or \"\").strip() \\\n        if isinstance(parsed, dict) else \"\"\n    _record_usage(model, None, bool(text), started)\n    if not text:\n        return None, \"no speech recognised\"\n    return text, \"\"\n\n\ndef describe_image(data: bytes, mime: str, system: str, prompt: str,\n                   timeout: Optional[float] = None,\n                   runtime: Optional[Dict[str, Any]] = None,\n                   max_tokens: int = 0\n                   ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode multimodal chat call with an inline image (data URI,\n    the OpenAI-compatible shape Gemini and OpenAI both accept).\n    Returns (parsed object, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty image\"\n    config = runtime or vision_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"image understanding not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    import base64 as _b64\n\n    data_uri = (\"data:\" + (str(mime or \"image/jpeg\")[:40]) + \";base64,\"\n                + _b64.b64encode(data).decode(\"ascii\"))\n    model = str(config.get(\"model\") or MODEL)\n    payload = {\n        \"model\": model,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": [\n                {\"type\": \"text\", \"text\": prompt},\n                {\"type\": \"image_url\", \"image_url\": {\"url\": data_uri}},\n            ]},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": int(max_tokens or VISION_MAX_TOKENS),\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n               \"Content-Type\": \"application/json\"}\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    body, error = _post_detail(base + \"/chat/completions\", headers, payload,\n                               float(timeout or VISION_TIMEOUT_SECONDS))\n    usage = body.get(\"usage\") if isinstance(body, dict) else None\n    if not isinstance(body, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    try:\n        content = body[\"choices\"][0][\"message\"][\"content\"]\n        parsed = json.loads(content)\n    except Exception:\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    if not isinstance(parsed, dict):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    _record_usage(model, usage, True, started)\n    return parsed, \"\"\n\n\n# ---------------------------------------------------------------------------\n# Ask OmniFlow AI (\u00a7227) - the owner's assistant: own key group, multi-turn\n# ---------------------------------------------------------------------------\n\nASSISTANT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_ASSISTANT_TIMEOUT\", \"20\") or 20)\n\n\ndef assistant_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.assistant_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef chat_messages_json(messages: List[Dict[str, str]],\n                       runtime: Optional[Dict[str, Any]] = None,\n                       max_tokens: int = 700,\n                       timeout: Optional[float] = None\n                       ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode chat call over a whole message list (system + history\n    + tool results). Returns (parsed object, \"\") or (None, reason) where\n    reason is not_configured | blocked | a short provider error. Gated by\n    the platform AI controls and recorded in the usage ledger.\"\"\"\n    config = runtime or assistant_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"not_configured\"\n    if _gated():\n        return None, \"blocked\"\n    model = str(config.get(\"model\") or MODEL)\n    targets = [{\"provider\": \"\", \"route\": \"\", \"model\": model,\n                \"api_key\": str(config[\"api_key\"]),\n                \"base_url\": str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")}]\n    # \u00a7229: the router's secondary provider covers an assistant outage\n    try:\n        import portal_model_router\n\n        backup = portal_model_router.failover_for(model)\n    except Exception:\n        backup = None\n    if backup and backup[\"api_key\"] != targets[0][\"api_key\"]:\n        targets.append(backup)\n    error = \"\"\n    for target in targets:\n        payload = {\n            \"model\": target[\"model\"],\n            \"messages\": messages,\n            \"temperature\": 0.2,\n            \"max_tokens\": int(max_tokens or 700),\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n                   \"Content-Type\": \"application/json\"}\n        started = time.time()\n        body, error = _post_detail(target[\"base_url\"] + \"/chat/completions\",\n                                   headers, payload,\n                                   float(timeout or ASSISTANT_TIMEOUT_SECONDS))\n        usage = body.get(\"usage\") if isinstance(body, dict) else None\n        try:\n            parsed = json.loads(body[\"choices\"][0][\"message\"][\"content\"])\n        except Exception:\n            parsed = None\n        if isinstance(parsed, dict):\n            _record_routed(target[\"model\"], usage, True, started, target[\"route\"])\n            return parsed, \"\"\n        _record_routed(target[\"model\"], usage, False, started, target[\"route\"])\n        if isinstance(body, dict):\n            break  # the provider answered; not an outage\n    return None, error or \"unexpected response\"\n");
writeNewRepair("OmniFlow-Control-Plane/portal_llm.py", "def _route_targets(", true,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float,\n                  route: str = \"\") -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\n    ``route`` (\u00a7229) is only passed when the model router changed the\n    target (fast | smart | failover); plain AI-engine calls look as before.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        extra = {\"route\": route} if route else {}\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model,\n            int(usage.get(\"prompt_tokens\") or 0),\n            int(usage.get(\"completion_tokens\") or 0),\n            int((time.time() - started) * 1000), ok, cur=cur,\n            agent_id=agent_id, **extra)\n    except Exception:\n        pass\n\n\ndef _record_routed(model: str, usage: Any, ok: bool, started: float,\n                   route: str) -> None:\n    # tests replace _record_usage with a 4-argument stub: keep that shape\n    # for every call the router did not change\n    if route:\n        _record_usage(model, usage, ok, started, route=route)\n    else:\n        _record_usage(model, usage, ok, started)\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any],\n                    timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(\n                request, timeout=timeout or TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef _route_targets(runtime: Dict[str, Any]) -> List[Dict[str, Any]]:\n    \"\"\"Model router (\u00a7229): [chosen target] or [chosen, failover]. Falls\n    back to the AI engine alone when the router is missing or broken.\"\"\"\n    main = {\"provider\": \"primary\",\n            \"base_url\": str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\"),\n            \"api_key\": str(runtime.get(\"api_key\") or \"\"),\n            \"model\": str(runtime.get(\"model\") or MODEL), \"route\": \"\"}\n    try:\n        import portal_model_router\n\n        return portal_model_router.plan(current_scope()[0], main) or [main]\n    except Exception:\n        return [main]\n\n\ndef _note_provider(target: Dict[str, Any], ok: bool) -> None:\n    try:\n        import portal_model_router\n\n        portal_model_router.note(target.get(\"provider\", \"\"), ok)\n    except Exception:\n        pass\n\n\ndef chat_json(system: str, user: str, max_tokens: int = 120,\n              timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\n    ``timeout`` overrides OF_LLM_TIMEOUT_SECONDS for one long answer\n    (e.g. the website analyzer's extraction). The model router picks the\n    model for the current usage scope and fails over to the secondary\n    provider when the chosen one does not answer.\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    for target in _route_targets(runtime):\n        payload = {\n            \"model\": target[\"model\"] or MODEL,\n            \"messages\": [\n                {\"role\": \"system\", \"content\": system},\n                {\"role\": \"user\", \"content\": user},\n            ],\n            \"temperature\": 0,\n            \"max_tokens\": max_tokens,\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\n            \"Authorization\": \"Bearer \" + str(target[\"api_key\"]),\n            \"Content-Type\": \"application/json\",\n        }\n        base = str(target[\"base_url\"] or BASE_URL).rstrip(\"/\")\n        model = str(payload[\"model\"])\n        route = str(target.get(\"route\") or \"\")\n        started = time.time()\n        last_usage = None\n        answered = False\n        for _ in range(ATTEMPTS):\n            if timeout:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload, timeout=timeout)\n            else:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload)\n            if not data:\n                continue\n            answered = True\n            last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n            try:\n                content = data[\"choices\"][0][\"message\"][\"content\"]\n                parsed = json.loads(content)\n            except Exception:\n                continue\n            if isinstance(parsed, dict):\n                _note_provider(target, True)\n                _record_routed(model, last_usage, True, started, route)\n                return parsed\n        _note_provider(target, answered)\n        _record_routed(model, last_usage, False, started, route)\n        if answered:\n            # the provider is up; an unusable answer is not failed over\n            return None\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n\n# ---------------------------------------------------------------------------\n# D5 media understanding: speech-to-text + image understanding. Same\n# contract as chat/embeddings: gated (kill switch / daily cap), one ledger\n# row per call under the caller's usage_scope, (result, error), never raises.\n# ---------------------------------------------------------------------------\n\nSTT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_STT_TIMEOUT_SECONDS\", \"20\") or 20)\nVISION_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_VISION_TIMEOUT_SECONDS\", \"15\") or 15)\nVISION_MAX_TOKENS = max(64, min(1024, int(\n    os.environ.get(\"OF_VISION_MAX_TOKENS\", \"300\") or 300)))\n\n\ndef stt_runtime() -> Optional[Dict[str, str]]:\n    \"\"\"Resolved speech-to-text endpoint (portal_media owns the defaults:\n    admin panel -> env -> OpenAI whisper). None when no key is saved.\"\"\"\n    try:\n        import portal_media\n\n        resolved = portal_media._stt_config()\n    except Exception:\n        resolved = None\n    if not resolved:\n        return None\n    base, key, model = resolved\n    return {\"base_url\": base, \"api_key\": key, \"model\": model}\n\n\ndef vision_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.vision_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef transcribe_audio(data: bytes, mime: str, filename: str = \"voice-note\",\n                     language: str = \"\", timeout: Optional[float] = None,\n                     runtime: Optional[Dict[str, str]] = None\n                     ) -> Tuple[Optional[str], str]:\n    \"\"\"Speech-to-text via the OpenAI-compatible /audio/transcriptions\n    endpoint (Whisper, Groq, ...). Returns (text, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty audio\"\n    config = runtime or stt_runtime()\n    if not config or not config.get(\"api_key\"):\n        return None, \"speech-to-text not configured\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    try:\n        import portal_media\n\n        fields = {\"model\": str(config.get(\"model\") or \"\")}\n        if language:\n            fields[\"language\"] = str(language)[:8]\n        body, boundary = portal_media._multipart_body(\n            fields, \"file\", str(filename or \"voice-note\")[:80],\n            str(mime or \"audio/ogg\")[:80], data)\n    except Exception as error:\n        return None, \"could not build the upload: \" + str(error)[:80]\n    model = str(config.get(\"model\") or \"\")\n    started = time.time()\n    try:\n        request = urllib.request.Request(\n            str(config[\"base_url\"]).rstrip(\"/\") + \"/audio/transcriptions\",\n            data=body, method=\"POST\")\n        request.add_header(\"Content-Type\",\n                           \"multipart/form-data; boundary=\" + boundary)\n        request.add_header(\"Authorization\", \"Bearer \" + str(config[\"api_key\"]))\n        with urllib.request.urlopen(\n                request, timeout=float(timeout or STT_TIMEOUT_SECONDS)) as resp:\n            parsed = json.loads(resp.read().decode(\"utf-8\", \"replace\"))\n    except urllib.error.HTTPError as error:\n        _record_usage(model, None, False, started)\n        return None, \"HTTP \" + str(error.code)\n    except Exception as error:\n        _record_usage(model, None, False, started)\n        return None, type(error).__name__ + \": \" + str(error)[:100]\n    text = str((parsed or {}).get(\"text\") or \"\").strip() \\\n        if isinstance(parsed, dict) else \"\"\n    _record_usage(model, None, bool(text), started)\n    if not text:\n        return None, \"no speech recognised\"\n    return text, \"\"\n\n\ndef describe_image(data: bytes, mime: str, system: str, prompt: str,\n                   timeout: Optional[float] = None,\n                   runtime: Optional[Dict[str, Any]] = None,\n                   max_tokens: int = 0\n                   ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode multimodal chat call with an inline image (data URI,\n    the OpenAI-compatible shape Gemini and OpenAI both accept).\n    Returns (parsed object, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty image\"\n    config = runtime or vision_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"image understanding not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    import base64 as _b64\n\n    data_uri = (\"data:\" + (str(mime or \"image/jpeg\")[:40]) + \";base64,\"\n                + _b64.b64encode(data).decode(\"ascii\"))\n    model = str(config.get(\"model\") or MODEL)\n    payload = {\n        \"model\": model,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": [\n                {\"type\": \"text\", \"text\": prompt},\n                {\"type\": \"image_url\", \"image_url\": {\"url\": data_uri}},\n            ]},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": int(max_tokens or VISION_MAX_TOKENS),\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n               \"Content-Type\": \"application/json\"}\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    body, error = _post_detail(base + \"/chat/completions\", headers, payload,\n                               float(timeout or VISION_TIMEOUT_SECONDS))\n    usage = body.get(\"usage\") if isinstance(body, dict) else None\n    if not isinstance(body, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    try:\n        content = body[\"choices\"][0][\"message\"][\"content\"]\n        parsed = json.loads(content)\n    except Exception:\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    if not isinstance(parsed, dict):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    _record_usage(model, usage, True, started)\n    return parsed, \"\"\n\n\n# ---------------------------------------------------------------------------\n# Ask OmniFlow AI (\u00a7227) - the owner's assistant: own key group, multi-turn\n# ---------------------------------------------------------------------------\n\nASSISTANT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_ASSISTANT_TIMEOUT\", \"20\") or 20)\n\n\ndef assistant_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.assistant_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef chat_messages_json(messages: List[Dict[str, str]],\n                       runtime: Optional[Dict[str, Any]] = None,\n                       max_tokens: int = 700,\n                       timeout: Optional[float] = None\n                       ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode chat call over a whole message list (system + history\n    + tool results). Returns (parsed object, \"\") or (None, reason) where\n    reason is not_configured | blocked | a short provider error. Gated by\n    the platform AI controls and recorded in the usage ledger.\"\"\"\n    config = runtime or assistant_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"not_configured\"\n    if _gated():\n        return None, \"blocked\"\n    model = str(config.get(\"model\") or MODEL)\n    targets = [{\"provider\": \"\", \"route\": \"\", \"model\": model,\n                \"api_key\": str(config[\"api_key\"]),\n                \"base_url\": str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")}]\n    # \u00a7229: the router's secondary provider covers an assistant outage\n    try:\n        import portal_model_router\n\n        backup = portal_model_router.failover_for(model)\n    except Exception:\n        backup = None\n    if backup and backup[\"api_key\"] != targets[0][\"api_key\"]:\n        targets.append(backup)\n    error = \"\"\n    for target in targets:\n        payload = {\n            \"model\": target[\"model\"],\n            \"messages\": messages,\n            \"temperature\": 0.2,\n            \"max_tokens\": int(max_tokens or 700),\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n                   \"Content-Type\": \"application/json\"}\n        started = time.time()\n        body, error = _post_detail(target[\"base_url\"] + \"/chat/completions\",\n                                   headers, payload,\n                                   float(timeout or ASSISTANT_TIMEOUT_SECONDS))\n        usage = body.get(\"usage\") if isinstance(body, dict) else None\n        try:\n            parsed = json.loads(body[\"choices\"][0][\"message\"][\"content\"])\n        except Exception:\n            parsed = None\n        if isinstance(parsed, dict):\n            _record_routed(target[\"model\"], usage, True, started, target[\"route\"])\n            return parsed, \"\"\n        _record_routed(target[\"model\"], usage, False, started, target[\"route\"])\n        if isinstance(body, dict):\n            break  # the provider answered; not an outage\n    return None, error or \"unexpected response\"\n");
writeNewRepair("omniflow-backend-patch/portal_ai_usage.py", "ADD COLUMN IF NOT EXISTS route TEXT NOT NULL DEFAULT ''", false,
    "\"\"\"AI usage + cost ledger (MASTER-UPGRADE platform service).\n\nEvery real LLM call the platform makes goes through ``portal_llm.chat_json``;\nthat function now reports each call here (feature, model, prompt/completion\ntokens straight from the provider's ``usage`` block, latency, ok/failed).\nCallers tag their calls with ``portal_llm.usage_scope(feature, client_id,\ncur)``; a call without a scope is still counted (feature \"other\",\nworkspace 0 = platform).\n\nCost is an ESTIMATE from a price table the platform admin saves\n(Admin -> Integrations -> AI engine -> \"Model prices (JSON)\" =\n``{\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.60}}`` in USD per million\ntokens; ``\"default\"`` covers unlisted models; env ``OF_AI_PRICES_JSON`` is\nthe fallback). No prices saved = tokens only, cost shown as \"not\nconfigured\" - never a made-up number.\n\nLaws: recording is fail-soft (a ledger problem never fails the customer\nmessage); with a caller cursor the row rides that transaction behind a\nSAVEPOINT, otherwise one short connection; ``OF_AI_USAGE=0`` switches the\nledger off. Read API is tenant-scoped and open to API keys (read-only).\n\"\"\"\n\nimport json\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-ai-usage\")\n\nbp = Blueprint(\"portal_ai_usage\", __name__, url_prefix=\"/api/v1/portal\")\n\nTABLE = \"portal_ai_usage\"\nENABLED = os.environ.get(\n    \"OF_AI_USAGE\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\nMAX_DAYS = int(os.environ.get(\"OF_AI_USAGE_MAX_DAYS\", \"90\") or 90)\nDEFAULT_DAYS = 7\n\n#: feature key -> owner-facing label (the usage card renders from this).\nFEATURES = (\n    (\"brain\", \"AI Brain answers & drafts\"),\n    (\"workflow\", \"Workflow decisions\"),\n    (\"intent\", \"Intent classification\"),\n    (\"sentiment\", \"Sentiment\"),\n    (\"negotiation\", \"Negotiation replies\"),\n    (\"copy\", \"Broadcast copy\"),\n    (\"bi_narrative\", \"Business insights narrative\"),\n    (\"kb_embed\", \"Knowledge semantic index\"),\n    (\"ai_quality_label\", \"Labelled-set live checks\"),\n    (\"voice_call\", \"Phone AI assistant\"),\n    (\"voice_note\", \"Voice note transcription\"),\n    (\"vision\", \"Image understanding\"),\n    (\"kb_ocr\", \"Knowledge document reading (OCR)\"),\n    (\"site_analyzer\", \"Website analysis\"),\n    (\"assistant\", \"Ask OmniFlow AI (owner assistant)\"),\n    (\"other\", \"Other\"),\n)\nFEATURE_LABELS = dict(FEATURES)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_ai_usage (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL DEFAULT 0,\n  feature TEXT NOT NULL DEFAULT 'other',\n  model TEXT NOT NULL DEFAULT '',\n  prompt_tokens INTEGER NOT NULL DEFAULT 0,\n  completion_tokens INTEGER NOT NULL DEFAULT 0,\n  latency_ms INTEGER NOT NULL DEFAULT 0,\n  ok BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_client_time\n  ON portal_ai_usage (client_id, created_at DESC);\nALTER TABLE portal_ai_usage\n  ADD COLUMN IF NOT EXISTS agent_id BIGINT;\nCREATE INDEX IF NOT EXISTS idx_portal_ai_usage_agent\n  ON portal_ai_usage (client_id, agent_id, created_at DESC);\nALTER TABLE portal_ai_usage\n  ADD COLUMN IF NOT EXISTS route TEXT NOT NULL DEFAULT '';\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# write path\n# ---------------------------------------------------------------------------\n\ndef _insert(cur, client_id: int, feature: str, model: str, prompt_tokens: int,\n            completion_tokens: int, latency_ms: int, ok: bool,\n            agent_id: int = 0, route: str = \"\") -> None:\n    aid = int(agent_id or 0) or None\n    if route:\n        # \u00a7229 model router: fast | smart | failover | test\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(TABLE) +\n            \" (client_id, feature, model, prompt_tokens, completion_tokens,\"\n            \" latency_ms, ok, agent_id, route)\"\n            \" VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)\",\n            (int(client_id or 0), str(feature or \"other\")[:40],\n             str(model or \"\")[:80], max(0, int(prompt_tokens or 0)),\n             max(0, int(completion_tokens or 0)), max(0, int(latency_ms or 0)),\n             bool(ok), aid, str(route)[:20]),\n        )\n        return\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TABLE) +\n        \" (client_id, feature, model, prompt_tokens, completion_tokens,\"\n        \" latency_ms, ok, agent_id) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\",\n        (int(client_id or 0), str(feature or \"other\")[:40],\n         str(model or \"\")[:80], max(0, int(prompt_tokens or 0)),\n         max(0, int(completion_tokens or 0)), max(0, int(latency_ms or 0)),\n         bool(ok), aid),\n    )\n\n\ndef record(client_id: int, feature: str, model: str, prompt_tokens: int,\n           completion_tokens: int, latency_ms: int, ok: bool,\n           cur=None, agent_id: int = 0, route: str = \"\") -> bool:\n    \"\"\"Append one call to the ledger. Never raises; False when skipped.\n    ``route`` = what the model router did (blank = the AI engine).\"\"\"\n    if not ENABLED:\n        return False\n    feature = feature if feature in FEATURE_LABELS else \"other\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_usage\")\n            _ensure_ddl(cur)\n            _insert(cur, client_id, feature, model, prompt_tokens,\n                    completion_tokens, latency_ms, ok, agent_id=agent_id,\n                    **({\"route\": route} if route else {}))\n            cur.execute(\"RELEASE SAVEPOINT of_ai_usage\")\n            return True\n        except Exception as error:\n            logger.warning(\"ai usage record (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_usage\")\n            except Exception:\n                pass\n            return False\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                _ensure_ddl(own)\n                _insert(own, client_id, feature, model, prompt_tokens,\n                        completion_tokens, latency_ms, ok, agent_id=agent_id,\n                        **({\"route\": route} if route else {}))\n            conn.commit()\n        finally:\n            conn.close()\n        return True\n    except Exception as error:\n        logger.warning(\"ai usage record failed: %s\", error)\n        return False\n\n\n# ---------------------------------------------------------------------------\n# platform gate (admin AI Control Center): kill switch + daily call cap\n# ---------------------------------------------------------------------------\n\nGATE_KILL_SWITCH = \"kill_switch\"\nGATE_DAILY_CAP = \"daily_cap\"\n#: reasons -> owner-facing sentence (notification detail)\nGATE_MESSAGES = {\n    GATE_KILL_SWITCH: \"AI answering is paused platform-wide by the OmniFlow\"\n                      \" team. Replies and drafts resume automatically when\"\n                      \" the pause is lifted.\",\n    GATE_DAILY_CAP: \"This workspace reached its daily AI call limit. AI\"\n                    \" answers and drafts pause until the limit resets;\"\n                    \" human replies are unaffected.\",\n}\n\n\ndef _count_calls_since(cur, client_id: int, hours: int) -> int:\n    cur.execute(\n        \"SELECT COUNT(*) AS calls FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s\"\n        \" AND created_at > NOW() - make_interval(hours => %s)\",\n        (int(client_id or 0), int(hours)),\n    )\n    rows = portal_db.rows(cur)\n    return int((rows[0] if rows else {}).get(\"calls\") or 0)\n\n\ndef calls_since(client_id: int, hours: int = 24, cur=None) -> Optional[int]:\n    \"\"\"LLM calls this workspace made in the last ``hours`` (None when the\n    ledger cannot be read). With a caller cursor the query rides that\n    transaction behind a SAVEPOINT; otherwise one short connection.\"\"\"\n    if cur is not None:\n        try:\n            cur.execute(\"SAVEPOINT of_ai_gate\")\n            value = _count_calls_since(cur, client_id, hours)\n            cur.execute(\"RELEASE SAVEPOINT of_ai_gate\")\n            return value\n        except Exception as error:\n            logger.warning(\"ai gate count (tx) failed: %s\", error)\n            try:\n                cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_gate\")\n            except Exception:\n                pass\n            return None\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as own:\n                value = _count_calls_since(own, client_id, hours)\n            conn.commit()\n        finally:\n            conn.close()\n        return value\n    except Exception as error:\n        logger.warning(\"ai gate count failed: %s\", error)\n        return None\n\n\ndef gate(feature: str, client_id: int, cur=None) -> Optional[str]:\n    \"\"\"Platform gate every LLM call passes before the provider is called.\n\n    Returns None when the call may proceed, else the blocking reason\n    (``kill_switch`` | ``daily_cap``). Fail-open: a storage problem never\n    blocks a call. When a workspace hits its daily cap the owner gets ONE\n    in-app notification per day (dedupe key ``aicap:<client>:<day>``).\n    \"\"\"\n    try:\n        import platform_settings\n\n        controls = platform_settings.ai_controls()\n    except Exception:\n        return None\n    if controls.get(\"kill_switch\"):\n        return GATE_KILL_SWITCH\n    cap = int(controls.get(\"daily_call_cap\") or 0)\n    client_id = int(client_id or 0)\n    if cap <= 0 or client_id <= 0:\n        return None\n    used = calls_since(client_id, 24, cur=cur)\n    if used is None or used < cap:\n        return None\n    try:\n        import datetime as _dt\n\n        import portal_notify\n\n        day = _dt.datetime.utcnow().strftime(\"%Y%m%d\")\n        portal_notify.notify(\n            client_id, \"system\", \"Daily AI call limit reached\",\n            GATE_MESSAGES[GATE_DAILY_CAP] + \" (\" + str(used) + \"/\" + str(cap)\n            + \" calls in the last 24 hours.)\", severity=\"high\",\n            dedupe_key=\"aicap:\" + str(client_id) + \":\" + day)\n    except Exception:\n        pass\n    return GATE_DAILY_CAP\n\n\n# ---------------------------------------------------------------------------\n# prices + cost\n# ---------------------------------------------------------------------------\n\ndef prices() -> Dict[str, Dict[str, float]]:\n    \"\"\"{model: {\"input\": usd_per_1M, \"output\": usd_per_1M}} from the admin\n    panel (llm.prices_json) or OF_AI_PRICES_JSON; {} when not configured.\"\"\"\n    raw = \"\"\n    try:\n        import platform_settings\n\n        raw = str(platform_settings.get_setting(\"llm.prices_json\", \"\") or \"\")\n    except Exception:\n        raw = \"\"\n    if not raw.strip():\n        raw = os.environ.get(\"OF_AI_PRICES_JSON\", \"\")\n    return parse_prices(raw)\n\n\ndef parse_prices(raw: Any) -> Dict[str, Dict[str, float]]:\n    try:\n        data = json.loads(raw) if isinstance(raw, str) else raw\n    except Exception:\n        return {}\n    if not isinstance(data, dict):\n        return {}\n    out: Dict[str, Dict[str, float]] = {}\n    for model, value in data.items():\n        if not isinstance(value, dict):\n            continue\n        try:\n            entry = {\"input\": float(value.get(\"input\") or 0),\n                     \"output\": float(value.get(\"output\") or 0)}\n        except Exception:\n            continue\n        if entry[\"input\"] < 0 or entry[\"output\"] < 0:\n            continue\n        out[str(model).strip().lower()] = entry\n    return out\n\n\ndef estimate_cost(model: str, prompt_tokens: int, completion_tokens: int,\n                  table: Dict[str, Dict[str, float]]) -> Optional[float]:\n    \"\"\"USD for one call, or None when the model is not priced.\"\"\"\n    if not table:\n        return None\n    price = table.get(str(model or \"\").strip().lower()) or table.get(\"default\")\n    if not price:\n        return None\n    return round((max(0, int(prompt_tokens or 0)) * price[\"input\"]\n                  + max(0, int(completion_tokens or 0)) * price[\"output\"])\n                 / 1000000.0, 6)\n\n\n# ---------------------------------------------------------------------------\n# read path\n# ---------------------------------------------------------------------------\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef usage_report(cur, client_id: int, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Totals + per-feature / per-model / per-day rollups for the window.\"\"\"\n    days = _days(days)\n    cur.execute(\n        \"SELECT feature, model, ok, agent_id, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,\"\n        \" COALESCE(SUM(completion_tokens), 0) AS completion_tokens,\"\n        \" COALESCE(AVG(latency_ms), 0) AS avg_latency_ms\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY feature, model, ok, agent_id\",\n        (client_id, days),\n    )\n    groups = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT DATE(created_at) AS day, COUNT(*) AS calls,\"\n        \" COALESCE(SUM(prompt_tokens + completion_tokens), 0) AS tokens\"\n        \" FROM \" + portal_db._q(TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY DATE(created_at) ORDER BY day\",\n        (client_id, days),\n    )\n    daily = portal_db.rows(cur)\n    table = prices()\n    totals = {\"calls\": 0, \"failed\": 0, \"prompt_tokens\": 0,\n              \"completion_tokens\": 0, \"latency_weighted\": 0.0,\n              \"cost_usd\": 0.0, \"unpriced_calls\": 0}\n    by_feature: Dict[str, Dict[str, Any]] = {}\n    by_model: Dict[str, Dict[str, Any]] = {}\n    by_agent: Dict[int, Dict[str, Any]] = {}\n    for row in groups:\n        calls = int(row.get(\"calls\") or 0)\n        p_tok = int(row.get(\"prompt_tokens\") or 0)\n        c_tok = int(row.get(\"completion_tokens\") or 0)\n        ok = bool(row.get(\"ok\"))\n        model = str(row.get(\"model\") or \"\")\n        feature = str(row.get(\"feature\") or \"other\")\n        try:\n            agent_id = int(row.get(\"agent_id\") or 0)\n        except Exception:\n            agent_id = 0\n        cost = estimate_cost(model, p_tok, c_tok, table)\n        totals[\"calls\"] += calls\n        totals[\"failed\"] += 0 if ok else calls\n        totals[\"prompt_tokens\"] += p_tok\n        totals[\"completion_tokens\"] += c_tok\n        totals[\"latency_weighted\"] += float(row.get(\"avg_latency_ms\") or 0) * calls\n        if cost is None:\n            totals[\"unpriced_calls\"] += calls\n        else:\n            totals[\"cost_usd\"] += cost\n        for bucket, key in ((by_feature, feature), (by_model, model or \"(unknown)\")):\n            entry = bucket.setdefault(key, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n            entry[\"calls\"] += calls\n            entry[\"failed\"] += 0 if ok else calls\n            entry[\"tokens\"] += p_tok + c_tok\n            if cost is None:\n                entry[\"priced\"] = False\n            else:\n                entry[\"cost_usd\"] += cost\n        # agent_id 0 / NULL = unattributed (default brain, no persona)\n        akey = agent_id if agent_id > 0 else 0\n        aentry = by_agent.setdefault(akey, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                            \"cost_usd\": 0.0, \"priced\": True})\n        aentry[\"calls\"] += calls\n        aentry[\"failed\"] += 0 if ok else calls\n        aentry[\"tokens\"] += p_tok + c_tok\n        if cost is None:\n            aentry[\"priced\"] = False\n        else:\n            aentry[\"cost_usd\"] += cost\n    priced = bool(table) and totals[\"unpriced_calls\"] == 0\n    calls = totals[\"calls\"]\n    agent_names: Dict[int, str] = {}\n    try:\n        ids = [aid for aid in by_agent.keys() if aid > 0]\n        if ids:\n            cur.execute(\n                \"SELECT id, name FROM \" + portal_db._q(\"portal_agents\") +\n                \" WHERE client_id = %s AND id = ANY(%s)\",\n                (client_id, ids),\n            )\n            for row in portal_db.rows(cur):\n                agent_names[int(row.get(\"id\") or 0)] = str(row.get(\"name\") or \"\")\n    except Exception as error:\n        logger.warning(\"ai usage agent names failed: %s\", error)\n    by_agent_list = []\n    for aid, v in sorted(by_agent.items(), key=lambda i: -i[1][\"calls\"]):\n        by_agent_list.append({\n            \"agent_id\": aid if aid > 0 else None,\n            \"name\": (agent_names.get(aid) if aid > 0 else None) or (\n                \"Unattributed\" if aid == 0 else (\"Agent #\" + str(aid))),\n            \"calls\": v[\"calls\"],\n            \"failed\": v[\"failed\"],\n            \"tokens\": v[\"tokens\"],\n            \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None,\n            \"share\": round(v[\"calls\"] / calls, 3) if calls else 0.0,\n        })\n    return {\n        \"days\": days,\n        \"totals\": {\n            \"calls\": calls,\n            \"failed\": totals[\"failed\"],\n            \"prompt_tokens\": totals[\"prompt_tokens\"],\n            \"completion_tokens\": totals[\"completion_tokens\"],\n            \"tokens\": totals[\"prompt_tokens\"] + totals[\"completion_tokens\"],\n            \"avg_latency_ms\": (int(totals[\"latency_weighted\"] / calls)\n                               if calls else 0),\n            \"cost_usd\": round(totals[\"cost_usd\"], 4) if priced else None,\n            \"priced\": priced,\n            \"unpriced_calls\": totals[\"unpriced_calls\"],\n        },\n        \"by_feature\": [\n            {\"feature\": key, \"label\": FEATURE_LABELS.get(key, key),\n             \"calls\": v[\"calls\"], \"failed\": v[\"failed\"], \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_feature.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_model\": [\n            {\"model\": key, \"calls\": v[\"calls\"], \"failed\": v[\"failed\"],\n             \"tokens\": v[\"tokens\"],\n             \"cost_usd\": round(v[\"cost_usd\"], 4) if v[\"priced\"] and table else None}\n            for key, v in sorted(by_model.items(), key=lambda i: -i[1][\"calls\"])\n        ],\n        \"by_day\": [\n            {\"day\": (row.get(\"day\").isoformat() if hasattr(row.get(\"day\"), \"isoformat\")\n                     else str(row.get(\"day\"))),\n             \"calls\": int(row.get(\"calls\") or 0),\n             \"tokens\": int(row.get(\"tokens\") or 0)}\n            for row in daily\n        ],\n        \"prices_configured\": bool(table),\n        \"features\": [{\"key\": k, \"label\": l} for k, l in FEATURES],\n        \"by_agent\": by_agent_list,\n    }\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/ai/usage\")\ndef get_usage():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            report = usage_report(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(report), 200\n");
